// === Tab: mySketch ===
let system;

OPC.slider('life', 700, 0, 2000, 1);
OPC.slider('gravity', 0.08, -5, 5, 0.01);
OPC.slider('size_decay', 0, -1, 1, 0.01);
OPC.slider('size', 25, 1, 30, 1);
OPC.slider('BackgroundR', 88, 0, 255, 1);
OPC.slider('BackgroundG', 25, 0, 255, 1);
OPC.slider('BackgroundB', 217, 0, 255, 1);
OPC.slider('MouseCloseness',60,5,500,1);
OPC.slider('MouseForce',1,0.1,100,0.1)
OPC.toggle('ShowMouseBounds',false)


function setup() {
	createCanvas(windowWidth, windowHeight);
	system = new ParticleSystem(createVector(width / 2, windowHeight /12));
}

function draw() {
	background(color(BackgroundR,BackgroundG, BackgroundB));
	system.addParticle();
	system.run();
	if(ShowMouseBounds==true){
	circle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),MouseCloseness+MouseForce)}
}

// A simple Particle class
let Particle = function(position) {
	this.acceleration = createVector(0, gravity);
	this.velocity = createVector(random(-1, 1), random(-1, 1));
	this.position = position.copy();
	this.lifespan = life;
	this.bigness = size
};

Particle.prototype.run = function() {
	this.mouse();
	this.update();
	this.display();
};

Particle.prototype.mouse = function() {
	this.posRelativeToMouse = createVector(
  this.position.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),
  this.position.y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
	);
	this.distance = Math.sqrt(
  this.posRelativeToMouse.x * this.posRelativeToMouse.x +
  this.posRelativeToMouse.y * this.posRelativeToMouse.y
	);
  this.forceDirection = createVector(
  this.posRelativeToMouse.x / this.distance,
  this.posRelativeToMouse.y / this.distance,
 	);
	maxDistance = MouseCloseness;
	this.force = (maxDistance - this.distance)/maxDistance*MouseForce;
	if (this.force < 0) this.force = 0;
	this.vec = createVector(this.forceDirection.x * this.force,this.forceDirection.y * this.force)
  this.velocity.add(this.vec)
}

// Method to update position
Particle.prototype.update = function() {
	this.velocity.add(this.acceleration);
	this.position.add(this.velocity);
	this.lifespan -= 2;
	if(this.bigness>0){
	this.bigness -= size_decay;
	}
};

// Method to display
Particle.prototype.display = function() {
	stroke(200, this.lifespan);
	strokeWeight(0.001);
	fill(random(this.lifespan* 255, this.lifespan*256), this.lifespan/4, this.lifespan/8);
	ellipse(this.position.x, this.position.y, this.bigness, this.bigness);
};

// Is the particle still useful?
Particle.prototype.isDead = function() {
	return this.lifespan < 0;
};

let ParticleSystem = function(position) {
	this.origin = position.copy();
	this.particles = [];
};

ParticleSystem.prototype.addParticle = function() {
	this.particles.push(new Particle(this.origin));
};

ParticleSystem.prototype.run = function() {
	for (let i = this.particles.length - 1; i >= 0; i--) {
		let p = this.particles[i];
		p.run();
		if (p.isDead()) {
			this.particles.splice(i, 1);
		}
	}
};

